package minitracecmd

import (
	fields "github.com/go-go-golems/glazed/pkg/cmds/fields"
	"github.com/go-go-golems/glazed/pkg/cmds/layout"
)

// MinitraceCommandKind describes whether a catalog entry is a direct verb
// or an alias that points to another verb.
type MinitraceCommandKind string

const (
	MinitraceCommandVerb  MinitraceCommandKind = "verb"
	MinitraceCommandAlias MinitraceCommandKind = "alias"
)

// MinitraceCommandSpec is the parsed representation of a sqleton-style
// .sql file or .alias.yaml file. It contains all the metadata read from
// the YAML preamble / alias YAML body before path context is applied.
type MinitraceCommandSpec struct {
	// YAML-decoded preamble fields (sqleton-style .sql files)
	Name      string                 `yaml:"name"`
	Short     string                 `yaml:"short"`
	Long      string                 `yaml:"long,omitempty"`
	Layout    []*layout.Section      `yaml:"layout,omitempty"`
	Flags     []*fields.Definition   `yaml:"flags,omitempty"`
	Arguments []*fields.Definition   `yaml:"arguments,omitempty"`
	Tags      []string               `yaml:"tags,omitempty"`
	Metadata  map[string]any         `yaml:"metadata,omitempty"`

	// Fields populated from the file body or alias-specific keys
	Query      string               `yaml:"-"`
	AliasFor   string               `yaml:"aliasFor,omitempty"`
	AliasFlags map[string]any       `yaml:"flags,omitempty"`
	Kind       MinitraceCommandKind `yaml:"-"`
}

// Validate checks that a parsed spec is self-consistent for its Kind.
func (s *MinitraceCommandSpec) Validate() error {
	switch s.Kind {
	case MinitraceCommandVerb:
		if s.Name == "" {
			return ErrMissingName
		}
		if s.Short == "" {
			return ErrMissingShort
		}
		if s.Query == "" {
			return ErrMissingQuery
		}
		if s.AliasFor != "" {
			return ErrVerbCannotSetAliasFor
		}
	case MinitraceCommandAlias:
		if s.Name == "" {
			return ErrMissingName
		}
		if s.AliasFor == "" {
			return ErrMissingAliasTarget
		}
		if s.Query != "" {
			return ErrAliasCannotSetQuery
		}
	default:
		return ErrUnknownCommandKind
	}
	return nil
}

// MinitraceCommand is the canonical runtime / catalog representation of a
// query command. It combines the parsed spec with resolved path context,
// readonly status, and source location. This is what the CLI compiler,
// serve API, and frontend all work from.
type MinitraceCommand struct {
	// Core identity
	Name  string
	Folder string  // directory portion of the source path, "" for root
	Path   string  // slash-separated relative path used as stable identifier

	// Help text
	Short string
	Long  string

	// Glazed parameter definitions reused directly
	Layout    []*layout.Section
	Flags     []*fields.Definition
	Arguments []*fields.Definition

	// Categorisation
	Tags     []string
	Metadata map[string]any

	// Query body (verbs only)
	Query string

	// Alias fields (aliases only)
	AliasFor   string
	AliasFlags map[string]any

	// Kind and origin
	Kind       MinitraceCommandKind
	Readonly   bool  // always true for catalog-loaded commands
	SourceRoot string // name of the SourceRoot this was loaded from
	SourcePath string // FS-relative path used during load
}

package minitracecmd

import "strings"

// SourceKind classifies a file for the purposes of catalog loading.
type SourceKind int

const (
	SourceUnknown SourceKind = iota
	SourceSQLCommand
	SourceYAMLAlias
)

// DetectSourceKind returns the SourceKind for the given filesystem path.
// It uses only the file extension — use LooksLikeSqletonSQLCommand to
// confirm that a .sql file actually contains a sqleton preamble.
func DetectSourceKind(path string) SourceKind {
	lower := strings.ToLower(path)
	switch {
	case strings.HasSuffix(lower, ".alias.yaml"),
		strings.HasSuffix(lower, ".alias.yml"):
		return SourceYAMLAlias
	case strings.HasSuffix(lower, ".sql"):
		return SourceSQLCommand
	default:
		return SourceUnknown
	}
}

package minitracecmd

import (
	"io"
	"strings"

	"github.com/pkg/errors"
	"gopkg.in/yaml.v3"
)

// ParseSQLCommandSpec parses a sqleton-style .sql file whose contents are:
//   /* sqleton
//   name: session-list
//   short: List all sessions
//   ...
//   */
//   SELECT * FROM sessions;
func ParseSQLCommandSpec(path string, contents []byte) (*MinitraceCommandSpec, error) {
	metaText, body, err := splitSqletonSQLPreamble(path, contents)
	if err != nil {
		return nil, err
	}

	spec := &MinitraceCommandSpec{Kind: MinitraceCommandVerb}
	dec := yaml.NewDecoder(strings.NewReader(metaText))
	if err := dec.Decode(spec); err != nil {
		return nil, errors.Wrapf(err, "decode sqleton sql preamble: %s", path)
	}

	spec.Query = strings.TrimSpace(body)
	if err := spec.Validate(); err != nil {
		return nil, errors.Wrapf(err, "validate sqleton sql command: %s", path)
	}
	return spec, nil
}

// ParseSQLCommandSpecFromReader reads all contents from r and delegates to
// ParseSQLCommandSpec.
func ParseSQLCommandSpecFromReader(path string, r io.Reader) (*MinitraceCommandSpec, error) {
	contents, err := io.ReadAll(r)
	if err != nil {
		return nil, errors.Wrapf(err, "read sqleton sql command: %s", path)
	}
	return ParseSQLCommandSpec(path, contents)
}

// splitSqletonSQLPreamble splits the raw byte contents of a .sql file into
// the YAML metadata block and the SQL body. It enforces that the file starts
// with /* sqleton, that the block is properly terminated by */, and that
// neither the metadata nor the body is empty.
func splitSqletonSQLPreamble(path string, contents []byte) (meta string, body string, err error) {
	// Strip leading BOM or whitespace so the first characters are reliable.
	s := strings.TrimLeft(string(contents), "\ufeff\r\n\t ")
	if !strings.HasPrefix(s, "/*") {
		return "", "", errors.WithStack(ErrMissingPreamble)
	}

	end := strings.Index(s, "*/")
	if end == -1 {
		return "", "", errors.WithStack(ErrUnterminatedPreamble)
	}

	raw := strings.TrimSpace(s[2:end])
	if !strings.HasPrefix(raw, "sqleton") {
		return "", "", errors.WithStack(ErrInvalidPreambleMarker)
	}

	metadata := strings.TrimSpace(strings.TrimPrefix(raw, "sqleton"))
	body = strings.TrimSpace(s[end+2:])

	if metadata == "" {
		return "", "", errors.WithStack(ErrEmptyPreambleMetadata)
	}
	if body == "" {
		return "", "", errors.WithStack(ErrMissingQuery)
	}

	return metadata, body, nil
}

// LooksLikeSqletonSQLCommand is a lightweight check that a .sql file contains
// a sqleton preamble. Use this before committing to the full parse.
func LooksLikeSqletonSQLCommand(contents []byte) bool {
	_, _, err := splitSqletonSQLPreamble("<input>", contents)
	return err == nil
}

package minitracecmd

import (
	"io"
	"strings"

	"github.com/pkg/errors"
	"gopkg.in/yaml.v3"
)

// aliasYAML is the intermediate struct used to decode a .alias.yaml file.
// It maps directly to the documented sqleton alias schema.
type aliasYAML struct {
	Name     string         `yaml:"name"`
	Short    string         `yaml:"short,omitempty"`
	AliasFor string         `yaml:"aliasFor"`
	Flags    map[string]any `yaml:"flags,omitempty"`
}

// ParseAliasSpec parses a sqleton-style .alias.yaml file. The expected shape is:
//
//	name: codex-framework-summary
//	aliasFor: framework-summary
//	short: Framework summary filtered to Codex
//	flags:
//	  framework:
//	    - codex
func ParseAliasSpec(path string, contents []byte) (*MinitraceCommandSpec, error) {
	payload := &aliasYAML{}
	if err := yaml.Unmarshal(contents, payload); err != nil {
		return nil, errors.Wrapf(err, "decode alias yaml: %s", path)
	}

	spec := &MinitraceCommandSpec{
		Name:       strings.TrimSpace(payload.Name),
		Short:      strings.TrimSpace(payload.Short),
		AliasFor:   strings.TrimSpace(payload.AliasFor),
		AliasFlags: payload.Flags,
		Kind:       MinitraceCommandAlias,
	}
	if err := spec.Validate(); err != nil {
		return nil, errors.Wrapf(err, "validate alias yaml: %s", path)
	}
	return spec, nil
}

// ParseAliasSpecFromReader reads all contents from r and delegates to ParseAliasSpec.
func ParseAliasSpecFromReader(path string, r io.Reader) (*MinitraceCommandSpec, error) {
	contents, err := io.ReadAll(r)
	if err != nil {
		return nil, errors.Wrapf(err, "read alias yaml: %s", path)
	}
	return ParseAliasSpec(path, contents)
}

