package minitracecmd

import (
	"path/filepath"

	fields "github.com/go-go-golems/glazed/pkg/cmds/fields"
)

// CompileOptions are the contextual values applied during spec → command compilation.
type CompileOptions struct {
	Folder     string // slash-separated directory path relative to catalog root
	Path       string // slash-separated full relative path
	SourceRoot string // name of the SourceRoot this command came from
	SourcePath string // filesystem-relative path used during load
	Readonly   bool   // always true for catalog-loaded commands
}

// Compiler turns parsed MinitraceCommandSpecs into canonical MinitraceCommands.
// It applies path context, normalises optional boolean defaults, and validates
// the spec before producing the runtime catalog entry.
type Compiler struct{}

// Compile turns a spec into a command with the given context.
func (c *Compiler) Compile(spec *MinitraceCommandSpec, opts CompileOptions) (*MinitraceCommand, error) {
	if spec == nil {
		return nil, ErrNilSpec
	}
	if err := spec.Validate(); err != nil {
		return nil, err
	}

	return &MinitraceCommand{
		Name:       spec.Name,
		Folder:     filepath.ToSlash(opts.Folder),
		Path:       filepath.ToSlash(opts.Path),
		Short:      spec.Short,
		Long:       spec.Long,
		Layout:     spec.Layout,
		Flags:      normalizeOptionalBoolFlags(spec.Flags),
		Arguments:  spec.Arguments,
		Tags:       spec.Tags,
		Metadata:   spec.Metadata,
		Query:      spec.Query,
		AliasFor:   spec.AliasFor,
		AliasFlags: spec.AliasFlags,
		Kind:       spec.Kind,
		Readonly:   opts.Readonly,
		SourceRoot: opts.SourceRoot,
		SourcePath: opts.SourcePath,
	}, nil
}

// normalizeOptionalBoolFlags walks each flag and, for optional bools with no
// default, sets Default = false. This matches sqleton's behaviour and avoids
// ambiguous CLI semantics where an absent bool flag could be interpreted as
// either true or false.
func normalizeOptionalBoolFlags(flags []*fields.Definition) []*fields.Definition {
	if len(flags) == 0 {
		return nil
	}

	ret := make([]*fields.Definition, 0, len(flags))
	for _, flag := range flags {
		if flag == nil {
			continue
		}
		cloned := flag.Clone()
		if cloned.Type == fields.TypeBool && !cloned.Required && cloned.Default == nil {
			v := any(false)
			cloned.Default = &v
		}
		ret = append(ret, cloned)
	}
	return ret
}

package minitracecmd

import (
	"io/fs"
	"path/filepath"
	"sort"
	"strings"
)

// SourceRoot represents one directory tree that contributes commands to the catalog.
type SourceRoot struct {
	Name     string // human-readable name used as SourceRoot field
	FS       fs.FS  // filesystem to walk; embed.FS, os.DirFS, or fstest.MapFS
	RootDir  string // subdirectory within FS to treat as the root (usually ".")
	Readonly bool   // always true for catalog-loaded roots; reserved for future use
}

// Catalog holds all loaded MinitraceCommands indexed by path and by name.
// Path is the authoritative unique key (first-root-wins on duplicates).
type Catalog struct {
	Commands []*MinitraceCommand        // ordered by lexicographic Path
	ByPath   map[string]*MinitraceCommand
	ByName   map[string]*MinitraceCommand // verbs only; first-seen wins
}

// LoadCatalog walks all SourceRoots in order, parses each recognised file,
// compiles it into a MinitraceCommand, and assembles a merged Catalog.
// Earlier roots win when the same Path appears in multiple roots.
func LoadCatalog(roots []SourceRoot) (*Catalog, error) {
	compiler := &Compiler{}
	catalog := &Catalog{
		Commands: []*MinitraceCommand{},
		ByPath:   map[string]*MinitraceCommand{},
		ByName:   map[string]*MinitraceCommand{},
	}

	for _, root := range roots {
		err := fs.WalkDir(root.FS, root.RootDir, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() {
				return nil
			}

			kind := DetectSourceKind(path)
			if kind == SourceUnknown {
				return nil
			}

			b, err := fs.ReadFile(root.FS, path)
			if err != nil {
				return err
			}

			var spec *MinitraceCommandSpec
			switch kind {
			case SourceSQLCommand:
				if !LooksLikeSqletonSQLCommand(b) {
					return nil // plain .sql without sqleton preamble — skip
				}
				spec, err = ParseSQLCommandSpec(path, b)
			case SourceYAMLAlias:
				spec, err = ParseAliasSpec(path, b)
			}
			if err != nil {
				return err
			}

			// Derive Folder and Path from the root-relative file path.
			rel, err := filepath.Rel(root.RootDir, path)
			if err != nil {
				return err
			}
			rel = filepath.ToSlash(rel)
			folder := filepath.ToSlash(filepath.Dir(rel))
			if folder == "." {
				folder = ""
			}

			cmd, err := compiler.Compile(spec, CompileOptions{
				Folder:     folder,
				Path:       rel,
				SourceRoot: root.Name,
				SourcePath: path,
				Readonly:   true,
			})
			if err != nil {
				return err
			}

			// First root wins on duplicate Path.
			if _, exists := catalog.ByPath[cmd.Path]; exists {
				return nil
			}

			catalog.ByPath[cmd.Path] = cmd
			catalog.Commands = append(catalog.Commands, cmd)

			// First verb with this name wins on ByName.
			if cmd.Kind == MinitraceCommandVerb {
				if _, exists := catalog.ByName[cmd.Name]; !exists {
					catalog.ByName[cmd.Name] = cmd
				}
			}

			return nil
		})
		if err != nil {
			return nil, err
		}
	}

	// Sort for stable ordering.
	sort.Slice(catalog.Commands, func(i, j int) bool {
		return strings.Compare(catalog.Commands[i].Path, catalog.Commands[j].Path) < 0
	})

	if err := resolveAliases(catalog); err != nil {
		return nil, err
	}

	return catalog, nil
}

// resolveAliases checks that every alias entry references a verb that exists
// in ByName. It does not mutate the alias entry itself; alias resolution
// for execution is handled separately in the render layer.
func resolveAliases(c *Catalog) error {
	for _, cmd := range c.Commands {
		if cmd.Kind != MinitraceCommandAlias {
			continue
		}
		if _, ok := c.ByName[cmd.AliasFor]; !ok {
			return ErrAliasTargetNotFound
		}
	}
	return nil
}

package minitracecmd

import (
	"os"
	"testing"
)

func TestParseSQLCommandSpec_ValidFile(t *testing.T) {
	contents := []byte(`/* sqleton
name: session-list
short: List all sessions
long: Returns every row from the sessions table.
query: "List all sessions"
tags:
  - sessions
  - list
*/
SELECT * FROM sessions;`)
	spec, err := ParseSQLCommandSpec("session-list.sql", contents)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if spec.Name != "session-list" {
		t.Errorf("Name = %q, want %q", spec.Name, "session-list")
	}
	if spec.Short != "List all sessions" {
		t.Errorf("Short = %q, want %q", spec.Short, "List all sessions")
	}
	if spec.Long != "Returns every row from the sessions table." {
		t.Errorf("Long = %q, want %q", spec.Long, "Returns every row from the sessions table.")
	}
	if spec.Kind != MinitraceCommandVerb {
		t.Errorf("Kind = %v, want %v", spec.Kind, MinitraceCommandVerb)
	}
	query := "SELECT * FROM sessions;"
	if spec.Query != query {
		t.Errorf("Query = %q, want %q", spec.Query, query)
	}
	if len(spec.Tags) != 2 {
		t.Errorf("Tags len = %d, want 2", len(spec.Tags))
	}
}

func TestParseSQLCommandSpec_ValidFile_WithFlags(t *testing.T) {
	contents := []byte(`/* sqleton
name: framework-summary
short: Summarise one framework
flags:
  - name: framework
    type: choice
    help: Which framework to summarise
    choices:
      - codex
      - claude
      - gemini
    required: true
*/
SELECT * FROM frameworks WHERE name = '{{framework}}';`)
	spec, err := ParseSQLCommandSpec("framework-summary.sql", contents)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if spec.Name != "framework-summary" {
		t.Errorf("Name = %q, want %q", spec.Name, "framework-summary")
	}
	if len(spec.Flags) != 1 {
		t.Fatalf("Flags len = %d, want 1", len(spec.Flags))
	}
	flag := spec.Flags[0]
	if flag.Name != "framework" {
		t.Errorf("flag.Name = %q, want %q", flag.Name, "framework")
	}
	if flag.Type != "choice" {
		t.Errorf("flag.Type = %q, want %q", flag.Type, "choice")
	}
	if len(flag.Choices) != 3 {
		t.Errorf("flag.Choices len = %d, want 3", len(flag.Choices))
	}
}

func TestParseSQLCommandSpec_MissingPreamble(t *testing.T) {
	contents := []byte(`SELECT * FROM sessions;`)
	_, err := ParseSQLCommandSpec("session-list.sql", contents)
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if err != ErrMissingPreamble {
		t.Errorf("error = %v, want %v", err, ErrMissingPreamble)
	}
}

func TestParseSQLCommandSpec_UnterminatedPreamble(t *testing.T) {
	contents := []byte(`/* sqleton
name: session-list
short: List all sessions
SELECT * FROM sessions;`)
	_, err := ParseSQLCommandSpec("session-list.sql", contents)
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if err != ErrUnterminatedPreamble {
		t.Errorf("error = %v, want %v", err, ErrUnterminatedPreamble)
	}
}

func TestParseSQLCommandSpec_InvalidMarker(t *testing.T) {
	contents := []byte(`/* plain comment
name: session-list
short: List all sessions
*/
SELECT * FROM sessions;`)
	_, err := ParseSQLCommandSpec("session-list.sql", contents)
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if err != ErrInvalidPreambleMarker {
		t.Errorf("error = %v, want %v", err, ErrInvalidPreambleMarker)
	}
}

func TestParseSQLCommandSpec_EmptyPreambleMetadata(t *testing.T) {
	contents := []byte(`/* sqleton */
SELECT * FROM sessions;`)
	_, err := ParseSQLCommandSpec("session-list.sql", contents)
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if err != ErrEmptyPreambleMetadata {
		t.Errorf("error = %v, want %v", err, ErrEmptyPreambleMetadata)
	}
}

func TestParseSQLCommandSpec_MissingShort(t *testing.T) {
	contents := []byte(`/* sqleton
name: session-list
*/
SELECT * FROM sessions;`)
	_, err := ParseSQLCommandSpec("session-list.sql", contents)
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if err != ErrMissingShort {
		t.Errorf("error = %v, want %v", err, ErrMissingShort)
	}
}

func TestParseSQLCommandSpec_MissingQueryBody(t *testing.T) {
	contents := []byte(`/* sqleton
name: session-list
short: List all sessions
*/
`)
	_, err := ParseSQLCommandSpec("session-list.sql", contents)
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if err != ErrMissingQuery {
		t.Errorf("error = %v, want %v", err, ErrMissingQuery)
	}
}

func TestParseSQLCommandSpec_VerbCannotSetAliasFor(t *testing.T) {
	contents := []byte(`/* sqleton
name: session-list
short: List all sessions
aliasFor: other-command
*/
SELECT * FROM sessions;`)
	_, err := ParseSQLCommandSpec("session-list.sql", contents)
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if err != ErrVerbCannotSetAliasFor {
		t.Errorf("error = %v, want %v", err, ErrVerbCannotSetAliasFor)
	}
}

func TestParseSQLCommandSpec_BOMStripped(t *testing.T) {
	contents := []byte("\ufeff/* sqleton\nname: bom-test\nshort: BOM is stripped\n*/\nSELECT 1;")
	_, err := ParseSQLCommandSpec("bom-test.sql", contents)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
}

func TestParseSQLCommandSpec_WhitespaceBeforePreamble(t *testing.T) {
	contents := []byte("  \t\r\n/* sqleton\nname: ws-test\nshort: whitespace stripped\n*/\nSELECT 1;")
	_, err := ParseSQLCommandSpec("ws-test.sql", contents)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
}

func TestParseSQLCommandSpecFromReader(t *testing.T) {
	contents := []byte(`/* sqleton
name: from-reader
short: Loaded via reader
*/
SELECT 1;`)
	f := os.NopCloser(newFakeReader(string(contents)))
	spec, err := ParseSQLCommandSpecFromReader("from-reader.sql", f)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if spec.Name != "from-reader" {
		t.Errorf("Name = %q, want %q", spec.Name, "from-reader")
	}
}

func TestLooksLikeSqletonSQLCommand_True(t *testing.T) {
	contents := []byte(`/* sqleton
name: test
short: test
*/
SELECT 1;`)
	if !LooksLikeSqletonSQLCommand(contents) {
		t.Error("expected true for valid sqleton preamble")
	}
}

func TestLooksLikeSqletonSQLCommand_False(t *testing.T) {
	contents := []byte(`-- regular SQL comment
SELECT 1;`)
	if LooksLikeSqletonSQLCommand(contents) {
		t.Error("expected false for plain SQL without preamble")
	}
}

// fakeReader is a simple io.Reader that reads from a string.
type fakeReader string

func (f *fakeReader) Read(p []byte) (n int, _ error) {
	if len(*f) == 0 {
		return 0, io.EOF
	}
	n = copy(p, *f)
	*f = ""
	return n, nil
}

// os.NopCloser wraps a reader; use it as a workaround for the named import above.
func newFakeReader(s string) *fakeReader {
	r := fakeReader(s)
	return &r
}

// The io import is used by fakeReader; suppress unused warning in test.
var _ = os.NopCloser

