func TestCompiler_CompileVerb(t *testing.T) {
	spec := &MinitraceCommandSpec{
		Name:  "session-list",
		Short: "List all sessions",
		Long:  "Returns every row from the sessions table.",
		Query: "SELECT * FROM sessions;",
		Kind:  MinitraceCommandVerb,
	}
	opts := CompileOptions{
		Folder:     "queries",
		Path:       "queries/session-list.sql",
		SourceRoot: "core",
		SourcePath: "core/queries/session-list.sql",
		Readonly:   true,
	}
	c := &Compiler{}
	cmd, err := c.Compile(spec, opts)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cmd.Name != "session-list" {
		t.Errorf("Name = %q, want %q", cmd.Name, "session-list")
	}
	if cmd.Folder != "queries" {
		t.Errorf("Folder = %q, want %q", cmd.Folder, "queries")
	}
	if cmd.Path != "queries/session-list.sql" {
		t.Errorf("Path = %q, want %q", cmd.Path, "queries/session-list.sql")
	}
	if cmd.Query != "SELECT * FROM sessions;" {
		t.Errorf("Query = %q, want %q", cmd.Query, "SELECT * FROM sessions;")
	}
	if cmd.Kind != MinitraceCommandVerb {
		t.Errorf("Kind = %v, want %v", cmd.Kind, MinitraceCommandVerb)
	}
	if !cmd.Readonly {
		t.Error("Readonly = false, want true")
	}
	if cmd.SourceRoot != "core" {
		t.Errorf("SourceRoot = %q, want %q", cmd.SourceRoot, "core")
	}
}

func TestCompiler_CompileAlias(t *testing.T) {
	spec := &MinitraceCommandSpec{
		Name:       "codex-session-list",
		Short:      "Session list filtered to Codex",
		AliasFor:   "session-list",
		AliasFlags: map[string]any{"framework": []any{"codex"}},
		Kind:       MinitraceCommandAlias,
	}
	opts := CompileOptions{
