func TestCompiler_NormalizesOptionalBoolFlags(t *testing.T) {
	trueVal := true
	falseVal := false
	spec := &MinitraceCommandSpec{
		Name:  "test",
		Short: "Test",
		Query: "SELECT 1;",
		Kind:  MinitraceCommandVerb,
		Flags: []*fields.Definition{
			{
				Name:     "verbose",
				Type:     fields.TypeBool,
				Required: false,
				Default:  nil, // optional bool with no default — should be normalised to false
			},
			{
				Name:     "quiet",
				Type:     fields.TypeBool,
				Required: false,
				Default:  &trueVal, // already has a default — leave it alone
			},
			{
				Name:     "force",
				Type:     fields.TypeBool,
				Required: true, // required bool — leave alone
				Default:  nil,
			},
			{
				Name:     "summary",
				Type:     fields.TypeString, // non-bool — leave alone
				Default:  nil,
			},
		},
	}
	c := &Compiler{}
	cmd, err := c.Compile(spec, CompileOptions{})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	flags := cmd.Flags

	// verbose: optional bool with no default → normalized to false
	verbose := flags[0]
	if verbose.Default == nil {
		t.Error("verbose Default should be set (normalised to false)")
	} else if *verbose.Default != false {
		t.Errorf("verbose Default = %v, want false", *verbose.Default)
	}

	// quiet: already has a default — unchanged
	quiet := flags[1]
	if quiet.Default == nil {
		t.Error("quiet Default should be unchanged")
	} else if *quiet.Default != true {
		t.Errorf("quiet Default = %v, want true", *quiet.Default)
	}

	// force: required bool — leave alone even with nil default
	force := flags[2]
	if force.Default != nil {
		t.Errorf("force Default = %v, want nil (required bool unchanged)", *force.Default)
	}

	// summary: non-bool — unchanged
	summary := flags[3]
	if summary.Default != nil {
		t.Errorf("summary Default = %v, want nil (non-bool unchanged)", *summary.Default)
	}

	// Verify the original spec flags are NOT mutated.
	if spec.Flags[0].Default != nil {
		t.Error("original spec flag should not be mutated")
	}
}

func TestCompiler_FlagsAreCloned(t *testing.T) {
	spec := &MinitraceCommandSpec{
		Name:  "clone-test",
		Short: "Clone test",
		Query: "SELECT 1;",
		Kind:  MinitraceCommandVerb,
		Flags: []*fields.Definition{
			{
				Name:    "verbose",
				Type:    fields.TypeBool,
				Default: nil, // will be normalised to false
			},
		},
	}
	c := &Compiler{}
	cmd, err := c.Compile(spec, CompileOptions{})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	// The compiled command's flag should be a clone, not the same pointer.
	if cmd.Flags[0] == spec.Flags[0] {
		t.Error("compiled flag should be a clone, not the same pointer as spec flag")
	}
	// Mutating the compiled flag should not affect the spec.
	cmd.Flags[0].Name = "mutated"
	if spec.Flags[0].Name == "mutated" {
		t.Error("spec flag was mutated — Clone() is not working correctly")
	}
}

func TestCompiler_NilFlagsInSpec(t *testing.T) {
	spec := &MinitraceCommandSpec{
		Name:      "nil-flags-test",
		Short:     "Nil flags test",
		Query:     "SELECT 1;",
		Kind:      MinitraceCommandVerb,
		Flags:     nil,
		Arguments: nil,
	}
	c := &Compiler{}
	cmd, err := c.Compile(spec, CompileOptions{})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cmd.Flags != nil {
		t.Errorf("Flags = %v, want nil", cmd.Flags)
	}
	if cmd.Arguments != nil {
		t.Errorf("Arguments = %v, want nil", cmd.Arguments)
	}
}

func TestCompiler_FieldsArePreserved(t *testing.T) {
	tags := []string{"sessions", "list"}
	metadata := map[string]any{"author": "test", "version": 1}
	layoutExample := []*struct{ Title string }{{Title: "Main"}}

	spec := &MinitraceCommandSpec{
		Name:      "fields-test",
		Short:     "Fields test",
		Long:      "Long description",
		Query:     "SELECT 1;",
		Kind:      MinitraceCommandVerb,
		Tags:      tags,
		Metadata:  metadata,
		Layout:    nil, // keep nil for simplicity
	}
	c := &Compiler{}
	cmd, err := c.Compile(spec, CompileOptions{})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if !reflect.DeepEqual(cmd.Tags, tags) {
		t.Errorf("Tags = %v, want %v", cmd.Tags, tags)
	}
	if !reflect.DeepEqual(cmd.Metadata, metadata) {
		t.Errorf("Metadata = %v, want %v", cmd.Metadata, metadata)
	}
	_ = layoutExample // silence unused warning
}

package minitracecmd

import (
