func TestLoadCatalog_LoadsSQLAndAlias(t *testing.T) {
	m := fstest.MapFS{
		"session-list.sql": &fstest.MapFile{
			Data: []byte(`/* sqleton
name: session-list
short: List all sessions
*/
SELECT * FROM sessions;`),
		},
		"framework-summary.sql": &fstest.MapFile{
			Data: []byte(`/* sqleton
name: framework-summary
short: Summarise one framework
flags:
  - name: framework
    type: choice
    help: Framework name
    choices:
      - codex
      - claude
*/
SELECT * FROM frameworks WHERE name = '{{framework}}';`),
		},
		"codex-framework-summary.alias.yaml": &fstest.MapFile{
			Data: []byte(`name: codex-framework-summary
aliasFor: framework-summary
short: Framework summary for Codex
flags:
  framework:
    - codex
`),
		},
	}
	roots := []SourceRoot{
		{Name: "core", FS: m, RootDir: ".", Readonly: true},
	}
	catalog, err := LoadCatalog(roots)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(catalog.Commands) != 3 {
		t.Errorf("Commands len = %d, want 3", len(catalog.Commands))
	}
	if _, ok := catalog.ByPath["session-list.sql"]; !ok {
		t.Error("session-list.sql should be in ByPath")
	}
	if _, ok := catalog.ByPath["framework-summary.sql"]; !ok {
		t.Error("framework-summary.sql should be in ByPath")
	}
	if _, ok := catalog.ByPath["codex-framework-summary.alias.yaml"]; !ok {
		t.Error("codex-framework-summary.alias.yaml should be in ByPath")
	}
	if _, ok := catalog.ByName["session-list"]; !ok {
		t.Error("session-list should be in ByName")
	}
	if _, ok := catalog.ByName["framework-summary"]; !ok {
		t.Error("framework-summary should be in ByName")
	}
}

func TestLoadCatalog_FirstRootWinsOnDuplicatePath(t *testing.T) {
	m1 := fstest.MapFS{
		"session-list.sql": &fstest.MapFile{
			Data: []byte(`/* sqleton
name: session-list-from-root1
short: From root 1
*/
SELECT 1;`),
