	if catalog.Commands[0].Name != "session-list-from-root1" {
		t.Errorf("Name = %q, want %q (first root should win)", catalog.Commands[0].Name, "session-list-from-root1")
	}
	if catalog.Commands[0].SourceRoot != "root1" {
		t.Errorf("SourceRoot = %q, want %q", catalog.Commands[0].SourceRoot, "root1")
