func TestLoadCatalog_ByNameFirstVerbWins(t *testing.T) {
	m := fstest.MapFS{
		"commands/session-list.sql": &fstest.MapFile{
			Data: []byte(`/* sqleton
name: session-list
short: Session list from commands/
*/
SELECT * FROM sessions;`),
		},
	}
	// Root-level also has a session-list (different path, same name).
	m2 := fstest.MapFS{
		"session-list.sql": &fstest.MapFile{
			Data: []byte(`/* sqleton
name: session-list
short: Session list from root
*/
SELECT * FROM sessions;`),
		},
	}
	// root-level loads first (walk order), so it wins ByName.
	roots := []SourceRoot{
		{Name: "root-level", FS: m2, RootDir: ".", Readonly: true},
		{Name: "commands", FS: m, RootDir: ".", Readonly: true},
	}
	catalog, err := LoadCatalog(roots)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(catalog.Commands) != 2 {
		t.Fatalf("Commands len = %d, want 2", len(catalog.Commands))
	}
	byName := catalog.ByName["session-list"]
	if byName == nil {
		t.Fatal("session-list should be in ByName")
	}
	// Root-level was loaded first, so it wins ByName despite being lexicographically after commands/
	if byName.SourceRoot != "root-level" {
		t.Errorf("ByName SourceRoot = %q, want %q (first verb wins)", byName.SourceRoot, "root-level")
	}
