*/
SELECT 2;`),
		},
	}
	roots := []SourceRoot{
		{Name: "core", FS: m, RootDir: ".", Readonly: true},
	}
	catalog, err := LoadCatalog(roots)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(catalog.Commands) != 2 {
		t.Fatalf("Commands len = %d, want 2", len(catalog.Commands))
	}
	paths := map[string]bool{}
	folders := map[string]bool{}
	for _, cmd := range catalog.Commands {
		paths[cmd.Path] = true
		folders[cmd.Folder] = true
	}
	if !paths["queries/session-list.sql"] {
		t.Error("queries/session-list.sql should be in paths")
	}
	if !paths["queries/nested/deep.sql"] {
		t.Error("queries/nested/deep.sql should be in paths")
	}
	if folders["queries"] != folders["queries/nested"] || !folders["queries"] {
		t.Errorf("folders = %v, want both queries and queries/nested", folders)
	}
}

