		return nil, errors.Wrapf(err, "read sqleton sql command: %s", path)
	}
	return ParseSQLCommandSpec(path, contents)
}

// splitSqletonSQLPreamble splits the raw byte contents of a .sql file into
// the YAML metadata block and the SQL body. It enforces that the file starts
// with /* sqleton, that the block is properly terminated by */, and that
// neither the metadata nor the body is empty.
func splitSqletonSQLPreamble(path string, contents []byte) (string, string, error) {
	// Strip leading BOM or whitespace so the first characters are reliable.
	s := strings.TrimLeft(string(contents), "\ufeff\r\n\t ")
	if !strings.HasPrefix(s, "/*") {
		return "", "", errors.WithStack(ErrMissingPreamble)
	}

	end := strings.Index(s, "*/")
	if end == -1 {
		return "", "", errors.WithStack(ErrUnterminatedPreamble)
	}

	raw := strings.TrimSpace(s[2:end])
	if !strings.HasPrefix(raw, "sqleton") {
		return "", "", errors.WithStack(ErrInvalidPreambleMarker)
	}

	metadata := strings.TrimSpace(strings.TrimPrefix(raw, "sqleton"))
	body := strings.TrimSpace(s[end+2:])

	if metadata == "" {
		return "", "", errors.WithStack(ErrEmptyPreambleMetadata)
	}
	if body == "" {
		return "", "", errors.WithStack(ErrMissingQuery)
	}

	return metadata, body, nil
}

// LooksLikeSqletonSQLCommand is a lightweight check that a .sql file contains
// a structurally valid sqleton preamble (correct opening marker, properly
// terminated, non-empty metadata). It does NOT check for query body presence —
// that is a validation concern for ParseSQLCommandSpec.
func LooksLikeSqletonSQLCommand(contents []byte) bool {
	_, _, err := looksLikeSplitSqletonSQLPreamble(contents)
	return err == nil
}

// looksLikeSplitSqletonSQLPreamble is like splitSqletonSQLPreamble but does NOT
// require a non-empty body, only structural preamble validity. This is used by
// LooksLikeSqletonSQLCommand to filter candidate .sql files cheaply.
func looksLikeSplitSqletonSQLPreamble(contents []byte) (string, string, error) {
	s := strings.TrimLeft(string(contents), "\ufeff\r\n\t ")
	if !strings.HasPrefix(s, "/*") {
		return "", "", ErrMissingPreamble
	}
	end := strings.Index(s, "*/")
	if end == -1 {
		return "", "", ErrUnterminatedPreamble
	}
	raw := strings.TrimSpace(s[2:end])
	if !strings.HasPrefix(raw, "sqleton") {
		return "", "", ErrInvalidPreambleMarker
	}
	metadata := strings.TrimSpace(strings.TrimPrefix(raw, "sqleton"))
	body := strings.TrimSpace(s[end+2:])
	if metadata == "" {
		return "", "", ErrEmptyPreambleMetadata
	}
	return metadata, body, nil
}

